// operations/traceability/engine/services/LabelService.ts
var PAGE_W = 283.46;
var PAGE_H = 198.43;
var MARGIN = 8;
var QR_SIZE = 80;
var TEXT_X = 96;
var TEXT_W = 180;
function wrap(font, text2, size, maxWidth) {
  const words = text2.split(/\s+/).filter(Boolean);
  if (words.length === 0)
    return [""];
  const lines = [];
  let line = words[0];
  for (const word of words.slice(1)) {
    const candidate = `${line} ${word}`;
    if (font.widthOfTextAtSize(candidate, size) <= maxWidth)
      line = candidate;
    else {
      lines.push(line);
      line = word;
    }
  }
  lines.push(line);
  return lines;
}
function drawLabel(page, fonts, qr, lot) {
  page.drawImage(qr, {
    x: MARGIN,
    y: PAGE_H - MARGIN - QR_SIZE,
    width: QR_SIZE,
    height: QR_SIZE
  });
  let cursor = MARGIN;
  const line = (text2, size, font, color = rgb(0, 0, 0)) => {
    for (const part of wrap(font, text2, size, TEXT_W)) {
      page.drawText(part, { x: TEXT_X, y: PAGE_H - cursor - size, size, font, color });
      cursor += font.heightAtSize(size);
    }
  };
  line(lot.item_name, 9, fonts.bold);
  cursor += 2;
  if (lot.supplier_name) {
    line(`Furnizor: ${lot.supplier_name}`, 7, fonts.regular);
    cursor += 1;
  }
  if (lot.supplier_lot_ref) {
    line(`Lot furnizor: ${lot.supplier_lot_ref}`, 7, fonts.regular);
    cursor += 1;
  }
  if (lot.best_before_date) {
    line(`BBD: ${lot.best_before_date}`, 10, fonts.bold, rgb(1, 0, 0));
    cursor += 2;
  }
  line(`Cant: ${lot.quantity_remaining} ${lot.unit}`, 8, fonts.regular);
  cursor += 1;
  if (lot.warehouse) {
    const loc = [lot.warehouse, lot.row, lot.shelf].filter(Boolean).join(" / ");
    line(`Loc: ${loc}`, 7, fonts.regular);
    cursor += 1;
  }
  const lotText = `LOT: ${lot.lot_number}`;
  const lotWidth = fonts.bold.widthOfTextAtSize(lotText, 7);
  page.drawText(lotText, {
    x: (PAGE_W - lotWidth) / 2,
    y: PAGE_H - 165 - 7,
    size: 7,
    font: fonts.bold,
    color: rgb(0, 0, 0)
  });
}
var COVERED = COVERED_RANGES.split(",").map((part) => {
  const [a, b] = part.split("-");
  const start = Number(a);
  return [start, b === undefined ? start : Number(b)];
});
function covers(codePoint) {
  let lo = 0;
  let hi = COVERED.length - 1;
  while (lo <= hi) {
    const mid = lo + hi >> 1;
    const [start, end] = COVERED[mid];
    if (codePoint < start)
      hi = mid - 1;
    else if (codePoint > end)
      lo = mid + 1;
    else
      return true;
  }
  return false;
}
var LABELLED_FIELDS = [
  ["item_name", "the product name"],
  ["supplier_name", "the supplier name"],
  ["supplier_lot_ref", "the supplier's lot reference"],
  ["best_before_date", "the best-before date"],
  ["unit", "the unit"],
  ["warehouse", "the storage location"],
  ["row", "the storage location"],
  ["shelf", "the storage location"],
  ["lot_number", "the lot number"]
];
function assertPrintable(lot) {
  for (const [key2, field] of LABELLED_FIELDS) {
    const value = lot[key2];
    if (typeof value !== "string" || value.length === 0)
      continue;
    for (const ch of value) {
      const cp = ch.codePointAt(0);
      if (cp !== undefined && !covers(cp)) {
        throw new Error(`Cannot print ${field}: the label font has no glyph for "${ch}" ` + `(U+${cp.toString(16).toUpperCase().padStart(4, "0")}). ` + `The font covers Latin, Cyrillic, Greek and Arabic scripts, but not this one.`);
      }
    }
  }
}
async function render(lots, title2) {
  for (const lot of lots)
    assertPrintable(lot);
  const doc2 = await PDFDocument_default.create();
  doc2.setTitle(title2);
  doc2.registerFontkit(fontkit_es_default);
  const fonts = {
    regular: await doc2.embedFont(decodeFont(DEJAVU_MONO_BASE64), { subset: true }),
    bold: await doc2.embedFont(decodeFont(DEJAVU_MONO_BOLD_BASE64), { subset: true })
  };
  for (const lot of lots) {
    const qrDataUrl = await QRService.generateQRDataURL(lot.id);
    const qr = await doc2.embedPng(qrDataUrl);
    drawLabel(doc2.addPage([PAGE_W, PAGE_H]), fonts, qr, lot);
  }
  return Buffer.from(await doc2.save());
}

class LabelService {
  static async generateLabel(lot) {
    return render([lot], `Etichet\u0103 lot ${lot.lot_number}`);
  }
  static async generateBatchLabels(lots) {
    if (lots.length === 0)
      throw new Error("No lots to label");
    return render(lots, `Etichete \u2014 ${lots.length} loturi`);
  }
}

// operations/traceability/engine/routes/labels.ts
function labelFailure(err) {
  const message = err instanceof Error ? err.message : "";
  return message.startsWith("Cannot print ") ? { error: message, status: 422 } : null;
}
async function fetchLotDetails(dbh, lotId) {
  const row = await sql`
    SELECT l.id, l.lot_number, l.quantity_remaining, l.unit, l.best_before_date,
           i.name as item_name, i.allergens, i.storage_conditions,
           s.name as supplier_name, l.supplier_lot_ref,
           loc.warehouse, loc.row, loc.shelf
    FROM trace_lots l
    INNER JOIN trace_items i ON i.id = l.item_id
    LEFT JOIN trace_suppliers s ON s.id = l.supplier_id
    LEFT JOIN trace_locations loc ON loc.id = l.location_id
    WHERE l.id = ${lotId}
  `.execute(dbh);
  return row.rows[0];
}
function labelsRouter(ctx) {
  const { db } = ctx;
  const app = new Hono2;
  app.get("/:lot_id", async (c) => {
    const lot = await fetchLotDetails(db, c.req.param("lot_id"));
    if (!lot)
      return c.json({ error: "Lot neg\u0103sit / Lot not found" }, 404);
    let pdf;
    try {
      pdf = await LabelService.generateLabel(lot);
    } catch (err) {
      const refusal = labelFailure(err);
      if (!refusal)
        throw err;
      return c.json({ error: refusal.error }, refusal.status);
    }
    return new Response(new Uint8Array(pdf), {
      headers: {
        "Content-Type": "application/pdf",
        "Content-Disposition": `inline; filename="eticheta-${lot.lot_number}.pdf"`
      }
    });
  });
  app.post("/batch", zValidator("json", exports_external.object({ lot_ids: exports_external.array(exports_external.string().uuid()).min(1).max(50) })), async (c) => {
    const { lot_ids } = c.req.valid("json");
    const lots = await Promise.all(lot_ids.map((id) => fetchLotDetails(db, id)));
    const validLots = lots.filter(Boolean);
    if (!validLots.length)
      return c.json({ error: "Niciun lot valid / No valid lots" }, 404);
    let pdf;
    try {
      pdf = await LabelService.generateBatchLabels(validLots);
    } catch (err) {
      const refusal = labelFailure(err);
      if (!refusal)
        throw err;
      return c.json({ error: refusal.error }, refusal.status);
    }
    return new Response(new Uint8Array(pdf), {
      headers: {
        "Content-Type": "application/pdf",
        "Content-Disposition": 'inline; filename="etichete-batch.pdf"'
      }
    });
  });
  app.get("/:lot_id/qr-png", async (c) => {
    const exists = await sql`SELECT id FROM trace_lots WHERE id = ${c.req.param("lot_id")}`.execute(db);
    if (!exists.rows.length)
      return c.json({ error: "Lot neg\u0103sit / Lot not found" }, 404);
    const buffer2 = await QRService.generateQRBuffer(c.req.param("lot_id"));
    return new Response(new Uint8Array(buffer2), {
      headers: { "Content-Type": "image/png" }
    });
  });
  app.get("/:lot_id/qr-dataurl", async (c) => {
    const exists = await sql`SELECT id FROM trace_lots WHERE id = ${c.req.param("lot_id")}`.execute(db);
    if (!exists.rows.length)
      return c.json({ error: "Lot neg\u0103sit / Lot not found" }, 404);
    const dataUrl = await QRService.generateQRDataURL(c.req.param("lot_id"));
    return c.json({ data: dataUrl });
  });
  return app;
}

// operations/traceability/engine/routes/reports.ts
function toCSV(internals, rows, columns) {
  const header = columns.map((c) => internals.csvCell(c)).join(",");
  const lines = rows.map((r) => columns.map((c) => internals.csvCell(r[c] ?? "")).join(","));
  return [header, ...lines].join(`\r
`);
}
function acceptsCsv(c) {
  return c.req.header("Accept")?.includes("text/csv") || c.req.query("format") === "csv";
}
function isoDateParam(v2) {
  if (typeof v2 !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(v2))
    return null;
  const d = new Date(`${v2}T00:00:00Z`);
  return Number.isNaN(d.getTime()) || d.toISOString().slice(0, 10) !== v2 ? null : v2;
}
function filenamePart(v2) {
  return v2 && /^[\w.-]{1,40}$/.test(v2) ? v2 : "all";
}
function reportsRouter(ctx) {
  const { db } = ctx;
  const app = new Hono2;
  app.get("/ansvsa-traceability", async (c) => {
    const from = isoDateParam(c.req.query("from"));
    const to = isoDateParam(c.req.query("to"));
    if (!from || !to) {
      return c.json({
        error: "Parametrii from \u0219i to sunt obligatorii, \xEEn format AAAA-LL-ZZ / " + "from and to are required, as YYYY-MM-DD"
      }, 400);
    }
    const rows = await sql`
      SELECT
        l.lot_number as "Num\u0103r lot intern",
        i.code as "Cod produs",
        i.name as "Denumire produs",
        i.type as "Tip",
        l.lot_type as "Tip lot",
        s.name as "Furnizor",
        s.cui as "CUI furnizor",
        l.supplier_lot_ref as "Lot furnizor",
        l.quantity_initial as "Cantitate recep\u021Bionat\u0103",
        l.quantity_remaining as "Cantitate r\u0103mas\u0103",
        l.unit as "UM",
        l.reception_date as "Data recep\u021Bie",
        l.best_before_date as "Data valabilitate",
        l.production_date as "Data produc\u021Bie",
        l.invoice_ref as "Referin\u021B\u0103 factur\u0103",
        l.status as "Status",
        loc.warehouse as "Depozit",
        loc.row as "R\u00E2nd",
        loc.shelf as "Raft"
      FROM trace_lots l
      INNER JOIN trace_items i ON i.id = l.item_id
      LEFT JOIN trace_suppliers s ON s.id = l.supplier_id
      LEFT JOIN trace_locations loc ON loc.id = l.location_id
      WHERE l.reception_date BETWEEN ${from} AND ${to}
        OR l.created_at::date BETWEEN ${from} AND ${to}
      ORDER BY COALESCE(l.reception_date, l.created_at::date), l.lot_number
    `.execute(db);
    if (acceptsCsv(c)) {
      const cols = rows.rows.length > 0 ? Object.keys(rows.rows[0]) : [];
      return new Response(toCSV(ctx.internals, rows.rows, cols), {
        headers: {
          "Content-Type": "text/csv; charset=utf-8",
          "Content-Disposition": `attachment; filename="trasabilitate-ansvsa-${filenamePart(from)}-${filenamePart(to)}.csv"`
        }
      });
    }
    return c.json({ data: rows.rows, meta: { from, to, count: rows.rows.length } });
  });
  app.get("/reception-log", async (c) => {
    const from = isoDateParam(c.req.query("from"));
    const to = isoDateParam(c.req.query("to"));
    if (c.req.query("from") && !from)
      return c.json({ error: "from: AAAA-LL-ZZ / YYYY-MM-DD" }, 400);
    if (c.req.query("to") && !to)
      return c.json({ error: "to: AAAA-LL-ZZ / YYYY-MM-DD" }, 400);
    const rows = await sql`
      SELECT
        m.performed_at as "Data/Ora",
        l.lot_number as "Num\u0103r lot",
        i.name as "Produs",
        i.code as "Cod",
        m.quantity as "Cantitate",
        m.unit as "UM",
        s.name as "Furnizor",
        l.invoice_ref as "Factur\u0103",
        loc.warehouse as "Depozit",
        m.reference_number as "Referin\u021B\u0103"
      FROM trace_movements m
      INNER JOIN trace_lots l ON l.id = m.lot_id
      INNER JOIN trace_items i ON i.id = l.item_id
      LEFT JOIN trace_suppliers s ON s.id = l.supplier_id
      LEFT JOIN trace_locations loc ON loc.id = m.to_location_id
      WHERE m.type = 'reception'
        AND (${from ? sql`m.performed_at::date >= ${from}` : sql`TRUE`})
        AND (${to ? sql`m.performed_at::date <= ${to}` : sql`TRUE`})
      ORDER BY m.performed_at DESC
    `.execute(db);
    if (acceptsCsv(c)) {
      const cols = rows.rows.length > 0 ? Object.keys(rows.rows[0]) : [];
      return new Response(toCSV(ctx.internals, rows.rows, cols), {
        headers: {
          "Content-Type": "text/csv; charset=utf-8",
          "Content-Disposition": `attachment; filename="receptii-${filenamePart(from)}-${filenamePart(to)}.csv"`
        }
      });
    }
    return c.json({ data: rows.rows });
  });
  app.get("/consumption-log", async (c) => {
    const from = isoDateParam(c.req.query("from"));
    const to = isoDateParam(c.req.query("to"));
    if (c.req.query("from") && !from)
      return c.json({ error: "from: AAAA-LL-ZZ / YYYY-MM-DD" }, 400);
    if (c.req.query("to") && !to)
      return c.json({ error: "to: AAAA-LL-ZZ / YYYY-MM-DD" }, 400);
    const rows = await sql`
      SELECT
        c.scanned_at as "Data/Ora",
        l.lot_number as "Lot consumat",
        i.name as "Materie prim\u0103",
        c.quantity_used as "Cantitate",
        c.unit as "UM",
        po.order_number as "Ordin produc\u021Bie",
        ol.lot_number as "Lot finit",
        oi.name as "Produs finit"
      FROM trace_lot_consumptions c
      INNER JOIN trace_lots l ON l.id = c.lot_id
      INNER JOIN trace_items i ON i.id = l.item_id
      INNER JOIN trace_production_orders po ON po.id = c.production_order_id
      LEFT JOIN trace_lots ol ON ol.id = po.output_lot_id
      LEFT JOIN trace_items oi ON oi.id = ol.item_id
      WHERE (${from ? sql`c.scanned_at::date >= ${from}` : sql`TRUE`})
        AND (${to ? sql`c.scanned_at::date <= ${to}` : sql`TRUE`})
      ORDER BY c.scanned_at DESC
    `.execute(db);
    if (acceptsCsv(c)) {
      const cols = rows.rows.length > 0 ? Object.keys(rows.rows[0]) : [];
      return new Response(toCSV(ctx.internals, rows.rows, cols), {
        headers: {
          "Content-Type": "text/csv; charset=utf-8",
          "Content-Disposition": `attachment; filename="consumuri-${filenamePart(from)}-${filenamePart(to)}.csv"`
        }
      });
    }
    return c.json({ data: rows.rows });
  });
  app.get("/stock-snapshot", async (c) => {
    const rows = await sql`
      SELECT
        i.code as "Cod",
        i.name as "Produs",
        i.type as "Tip",
        i.category as "Categorie",
        l.lot_number as "Num\u0103r lot",
        l.quantity_remaining as "Cantitate disponibil\u0103",
        l.unit as "UM",
        l.best_before_date as "Valabil p\u00E2n\u0103",
        l.reception_date as "Data recep\u021Bie",
        s.name as "Furnizor",
        loc.warehouse as "Depozit",
        loc.row as "R\u00E2nd",
        loc.shelf as "Raft"
      FROM trace_lots l
      INNER JOIN trace_items i ON i.id = l.item_id
      LEFT JOIN trace_suppliers s ON s.id = l.supplier_id
      LEFT JOIN trace_locations loc ON loc.id = l.location_id
      WHERE l.status = 'available'
      ORDER BY i.name, l.best_before_date NULLS LAST
    `.execute(db);
    if (acceptsCsv(c)) {
      const cols = rows.rows.length > 0 ? Object.keys(rows.rows[0]) : [];
      return new Response(toCSV(ctx.internals, rows.rows, cols), {
        headers: {
          "Content-Type": "text/csv; charset=utf-8",
          "Content-Disposition": `attachment; filename="stoc-${new Date().toISOString().slice(0, 10)}.csv"`
        }
      });
    }
    return c.json({ data: rows.rows, meta: { generated_at: new Date().toISOString(), count: rows.rows.length } });
  });
  app.get("/haccp-log", async (c) => {
    const from = isoDateParam(c.req.query("from"));
    const to = isoDateParam(c.req.query("to"));
    if (c.req.query("from") && !from)
      return c.json({ error: "from: AAAA-LL-ZZ / YYYY-MM-DD" }, 400);
    if (c.req.query("to") && !to)
      return c.json({ error: "to: AAAA-LL-ZZ / YYYY-MM-DD" }, 400);
    const rows = await sql`
      SELECT
        po.order_number as "Ordin produc\u021Bie",
        po.completed_at as "Data/Ora finalizare",
        l.lot_number as "Lot finit",
        i.name as "Produs",
        po.actual_quantity as "Cantitate produs\u0103",
        po.unit as "UM",
        po.haccp_checks as "Verific\u0103ri CCP"
      FROM trace_production_orders po
      LEFT JOIN trace_lots l ON l.id = po.output_lot_id
      LEFT JOIN trace_items i ON i.id = l.item_id
      WHERE po.status = 'completed'
        AND (${from ? sql`po.completed_at::date >= ${from}` : sql`TRUE`})
        AND (${to ? sql`po.completed_at::date <= ${to}` : sql`TRUE`})
      ORDER BY po.completed_at DESC
    `.execute(db);
    return c.json({ data: rows.rows });
  });
  return app;
}

